+			/*
+			 * Cache the running sum of level-2 store counts on the
+			 * level-1 parent, mirroring c2c_he__add_sharing() above,
+			 * so hist_entry__child_stores() stays O(1).
+			 */
+			level1_c2c->child_stores += c2c_b->stats.store;
