+static int
+c2c_function_hists__init_output(struct perf_hpp_list *hpp_list, char *name,
+				struct perf_env *env __maybe_unused)
+{
+	struct c2c_fmt *c2c_fmt;
+	int level = 0;
+	int ret;
+
+	ret = get_function_format(name, &c2c_fmt);
